import{_ as p,a0 as l,w as i,s as a,ao as S,I as r,x as e,a1 as o,A as s}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const E=JSON.parse('{"title":"小白技巧：openSUSE设置服务服务通过防火墙 | LCTT x X-CMD","titleTemplate":false,"description":"小白技巧：openSUSE设置服务服务通过防火墙 | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"小白技巧：openSUSE设置服务服务通过防火墙 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"小白技巧：openSUSE设置服务服务通过防火墙 | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20141106 Quick Tip Allow Services Through Firewall In openSUSE","title":"小白技巧：openSUSE设置服务服务通过防火墙","tag":"201411","desc":""},"relativePath":"201411/20141106 Quick Tip Allow Services Through Firewall In openSUSE.md","filePath":"[post].md"}'),u={name:"201411/20141106 Quick Tip Allow Services Through Firewall In openSUSE.md"};function g(d,t,w,T,m,f){const n=l("Link");return i(),a("div",null,[t[13]||(t[13]=S('<h1 id="小白技巧-opensuse设置服务服务通过防火墙" tabindex="-1">小白技巧：openSUSE设置服务服务通过防火墙 <a class="header-anchor" href="#小白技巧-opensuse设置服务服务通过防火墙" aria-label="Permalink to “小白技巧：openSUSE设置服务服务通过防火墙”">​</a></h1><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/openSUSE.png" alt=""></p><p>正如你所知道的，在openSUSE/SUSE系统上，不是所有的服务是激活并且默认允许的。例如，<strong>ssh</strong>服务是默认不允许通过防火墙的。当然，这是一个安全措施，但是有时我们必须需要ssh服务从远程地点来连接服务器。</p><p>这个小教程将会展示如何允许服务，不单是ssh，也包括所有其他的服务，如http，ftp等，通过服务器。我们可以使用<strong>YaST</strong>命令允许服务通过防火墙，<strong>YaST</strong>命令是openSUSE和其企业版，默认安装配置工具。</p><p>首先，在菜单中打开YaST控制中心。选择<strong>Security and Users（安全和用户） -&gt; Firewall（防火墙）</strong></p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/openSUSE-13.1-Running-Oracle-VM-VirtualBox_001.png" alt=""></p><p>接下来，打开<strong>Allowed Services（已允许服务）</strong>选项卡；从Service to Allow（选择需要允许的服务）下拉框中选择<strong>Secure Shell Service（ssh服务）</strong>，然后 <strong>Add（增加）</strong>，<strong>Next（下一步）</strong>，最后<strong>Finish（完成）</strong>，搞定。</p><p><img src="http://180016988.r.cdn77.net/wp-content/uploads/2014/11/openSUSE-13.1-Running-Oracle-VM-VirtualBox_002.png" alt=""></p><p>就是如此简单！ssh服务已经允许通过防火墙，这样你就可以在远程系统连接这个系统了。就像这样，我们可以同样设置其他服务。</p><p>鼓掌！！</p><hr>',11)),r("p",null,[t[1]||(t[1]=e("via: ",-1)),o(n,{href:"http://www.unixmen.com/quick-tip-allow-services-firewall-opensuse/"},{default:s(()=>[...t[0]||(t[0]=[e("http://www.unixmen.com/quick-tip-allow-services-firewall-opensuse/",-1)])]),_:1})]),r("p",null,[t[5]||(t[5]=e("作者：",-1)),o(n,{href:"http://www.unixmen.com/author/sk/"},{default:s(()=>[...t[2]||(t[2]=[e("SK",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),o(n,{href:"http://www.vicyu.net"},{default:s(()=>[...t[3]||(t[3]=[e("VicYu/Vic020",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),o(n,{href:"https://github.com/wxy"},{default:s(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),r("p",null,[t[10]||(t[10]=e("本文由 ",-1)),o(n,{href:"https://github.com/LCTT/TranslateProject"},{default:s(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),o(n,{href:"http://linux.cn/"},{default:s(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const U=p(u,[["render",g]]);export{E as __pageData,U as default};
